use semio_framework_value_control_contract::{RetainedWorkPoll,RetainedWorkOutcome};
#[test]
fn pending_work_never_fabricates_a_settled_result(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../🎟️control/🧬️contract/⏳️poll/🧪️tests/cases.json")).unwrap();
 for row in corpus["cases"].as_array().unwrap(){let input=&row["input"];let poll:RetainedWorkPoll<String,String>=if input["type"]=="pending"{RetainedWorkPoll::Pending{work:input["work"].as_str().unwrap().parse::<u128>().unwrap()}}else{let turn=&input["turn"];RetainedWorkPoll::Complete(RetainedWorkOutcome{result:if let Some(value)=turn["result"]["ok"].as_str(){Ok(value.to_owned())}else{Err(turn["result"]["error"].as_str().unwrap().to_owned())},work:turn["work"].as_str().unwrap().parse::<u128>().unwrap()})};let expected=&row["expected"];assert_eq!(poll.work(),expected["work"].as_str().unwrap().parse::<u128>().unwrap());match poll{RetainedWorkPoll::Pending{..}=>{assert_eq!(expected["pending"],true);assert_eq!(expected["publish"],false)},RetainedWorkPoll::Complete(turn)=>{assert_eq!(expected["pending"],false);assert_eq!(expected["publish"],turn.result.is_ok())}}}
 for invalid in corpus["invalidWork"].as_array().unwrap(){let raw=invalid.as_str().unwrap();assert!(!raw.parse::<u128>().is_ok_and(|value|value.to_string()==raw))}
 let refusal=String::from("original refusal");let pointer=refusal.as_ptr();let poll:RetainedWorkPoll<String,String>=RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(refusal),work:0});match poll.map(|_|panic!("refused owner cannot publish")){RetainedWorkPoll::Complete(turn)=>assert_eq!(turn.result.unwrap_err().as_ptr(),pointer),_=>panic!("recorded completion cannot become pending")}
 let pending:RetainedWorkPoll<String,String>=RetainedWorkPoll::Pending{work:0};assert!(matches!(pending.map(|_|panic!("pending has no payload")),RetainedWorkPoll::Pending{work:0}));
}
